INSERT INTO compact_budget_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_model_budget WHERE total_tokens<0 OR warning_percent NOT BETWEEN 1 AND 100 OR free_only NOT IN (0,1) OR version<0 OR CHAR_LENGTH(model_id)=0;
INSERT INTO compact_budget_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_model_budget_attempt s LEFT JOIN `__SOURCE_SCHEMA__`.agent_model_budget b ON s.model_id=b.model_id WHERE b.model_id IS NULL;
INSERT INTO compact_budget_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_model_budget_observation s LEFT JOIN `__SOURCE_SCHEMA__`.agent_model_budget b ON s.model_id=b.model_id WHERE b.model_id IS NULL;
INSERT INTO compact_budget_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_model_budget_audit s LEFT JOIN `__SOURCE_SCHEMA__`.agent_model_budget b ON s.model_id=b.model_id WHERE b.model_id IS NULL;
INSERT INTO compact_budget_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_model_budget_attempt WHERE CHAR_LENGTH(attempt_id)=0 OR BINARY status NOT IN (BINARY 'STARTED',BINARY 'COMPLETED',BINARY 'FAILED',BINARY 'CANCELLED') OR input_tokens<0 OR output_tokens<0 OR cached_tokens<0 OR CAST(COALESCE(input_tokens,0) AS DECIMAL(65,0))+CAST(COALESCE(output_tokens,0) AS DECIMAL(65,0))>9223372036854775807;
INSERT INTO compact_budget_guard SELECT IF(COUNT(*)=0,1,0) FROM (SELECT model_id FROM `__SOURCE_SCHEMA__`.agent_model_budget_attempt GROUP BY model_id HAVING SUM(CAST(COALESCE(input_tokens,0) AS DECIMAL(65,0))+CAST(COALESCE(output_tokens,0) AS DECIMAL(65,0)))>9223372036854775807) invalid_totals;
INSERT INTO compact_budget_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_model_budget_observation WHERE actor_user_id<=0 OR remaining_tokens<0 OR CHAR_LENGTH(request_id)=0 OR NOT REGEXP_LIKE(request_sha256,'^[a-f0-9]{64}$','c');
INSERT INTO compact_budget_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_model_budget_audit WHERE actor_user_id<=0;
INSERT INTO llm_quota(scope_type,owner_user_id,model_id,period_key,total_tokens,reserved_tokens,spent_tokens,unreconciled_legacy_attempts,warning_percent,free_only,expires_at,version,updated_by,created_at,updated_at) SELECT 'MODEL',NULL,s.model_id,'TOTAL',s.total_tokens,0,(SELECT COALESCE(SUM(COALESCE(a.input_tokens,0)+COALESCE(a.output_tokens,0)),0) FROM `__SOURCE_SCHEMA__`.agent_model_budget_attempt a WHERE a.model_id=s.model_id),(SELECT COUNT(*) FROM `__SOURCE_SCHEMA__`.agent_model_budget_attempt a WHERE a.model_id=s.model_id AND (a.status<>'COMPLETED' OR a.finished_at IS NULL OR a.input_tokens IS NULL OR a.output_tokens IS NULL)),s.warning_percent,s.free_only,s.expires_at,s.version,s.updated_by,@compact_budget_imported_at,s.updated_at FROM `__SOURCE_SCHEMA__`.agent_model_budget s ORDER BY s.model_id;
INSERT INTO audit_event(event_id,kind,resource_type,resource_id,request_id,action,outcome,content_sha256,occurred_at,payload_version,payload_json,legacy_source,legacy_key) SELECT CONCAT('legacy-model-attempt-',s.id),'LLM_LEGACY_ATTEMPT','LLM_MODEL',s.model_id,s.attempt_id,'IMPORTED',s.status,SHA2(JSON_OBJECT('legacyId',CAST(s.id AS CHAR),'attemptId',s.attempt_id,'modelId',s.model_id,'status',s.status,'inputTokens',s.input_tokens,'outputTokens',s.output_tokens,'cachedTokens',s.cached_tokens,'startedAtUtc',DATE_FORMAT(s.started_at,'%Y-%m-%d %H:%i:%s.%f'),'finishedAtUtc',DATE_FORMAT(s.finished_at,'%Y-%m-%d %H:%i:%s.%f')),256),COALESCE(s.finished_at,s.started_at),1,JSON_OBJECT('legacyId',CAST(s.id AS CHAR),'attemptId',s.attempt_id,'modelId',s.model_id,'status',s.status,'inputTokens',s.input_tokens,'outputTokens',s.output_tokens,'cachedTokens',s.cached_tokens,'startedAtUtc',DATE_FORMAT(s.started_at,'%Y-%m-%d %H:%i:%s.%f'),'finishedAtUtc',DATE_FORMAT(s.finished_at,'%Y-%m-%d %H:%i:%s.%f')),'agent_model_budget_attempt',CAST(s.id AS CHAR) FROM `__SOURCE_SCHEMA__`.agent_model_budget_attempt s ORDER BY s.id;
INSERT INTO audit_event(event_id,kind,owner_user_id,actor_user_id,resource_type,resource_id,request_id,action,content_sha256,quantity,unit,request_scope,observed_at,occurred_at,payload_version,payload_json,legacy_source,legacy_key) SELECT CONCAT('legacy-model-observation-',s.id),'MODEL_QUOTA_OBSERVATION',s.actor_user_id,s.actor_user_id,'LLM_MODEL',s.model_id,s.request_id,'OBSERVATION',s.request_sha256,s.remaining_tokens,'TOKENS',CONCAT('OWNER:',s.actor_user_id),s.observed_at,s.created_at,1,JSON_OBJECT('sourceNote',s.source_note),'agent_model_budget_observation',CAST(s.id AS CHAR) FROM `__SOURCE_SCHEMA__`.agent_model_budget_observation s ORDER BY s.id;
INSERT INTO audit_event(event_id,kind,owner_user_id,actor_user_id,resource_type,resource_id,action,content_sha256,occurred_at,payload_version,payload_json,legacy_source,legacy_key) SELECT CONCAT('legacy-model-policy-audit-',s.id),'LLM_LEGACY_BUDGET_AUDIT',s.actor_user_id,s.actor_user_id,'LLM_MODEL',s.model_id,'IMPORTED',SHA2(JSON_OBJECT('legacyId',CAST(s.id AS CHAR),'modelId',s.model_id,'actorUserId',s.actor_user_id,'actionName',s.action_name,'version',s.version,'detailJson',CAST(s.detail_json AS CHAR),'createdAtUtc',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f')),256),s.created_at,1,JSON_OBJECT('legacyId',CAST(s.id AS CHAR),'modelId',s.model_id,'actorUserId',s.actor_user_id,'actionName',s.action_name,'version',s.version,'detailJson',CAST(s.detail_json AS CHAR),'createdAtUtc',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f')),'agent_model_budget_audit',CAST(s.id AS CHAR) FROM `__SOURCE_SCHEMA__`.agent_model_budget_audit s ORDER BY s.id;
INSERT INTO llm_usage(account_id,source_audit_event_id,entry_key,entry_type,reserved_delta,spent_delta,input_tokens,output_tokens,cached_tokens,request_sha256,created_at) SELECT q.id,e.id,'V64_ATTEMPT','IMPORTED_USAGE',0,COALESCE(s.input_tokens,0)+COALESCE(s.output_tokens,0),s.input_tokens,s.output_tokens,s.cached_tokens,SHA2(CONCAT('V64_IMPORT',CHAR(10),e.payload_json),256),COALESCE(s.finished_at,s.started_at) FROM `__SOURCE_SCHEMA__`.agent_model_budget_attempt s JOIN llm_quota q ON q.scope_type='MODEL' AND q.owner_user_id IS NULL AND q.period_key='TOTAL' AND q.model_id=s.model_id JOIN audit_event e ON BINARY e.legacy_source=BINARY 'agent_model_budget_attempt' AND BINARY e.legacy_key=BINARY CAST(s.id AS CHAR) AND e.kind='LLM_LEGACY_ATTEMPT' ORDER BY s.id;
INSERT INTO compact_budget_guard SELECT IF((SELECT COUNT(*) FROM llm_quota WHERE scope_type='MODEL')=(SELECT COUNT(*) FROM `__SOURCE_SCHEMA__`.agent_model_budget),1,0);
INSERT INTO compact_budget_guard SELECT IF((SELECT COUNT(*) FROM audit_event WHERE kind='LLM_LEGACY_ATTEMPT')=(SELECT COUNT(*) FROM `__SOURCE_SCHEMA__`.agent_model_budget_attempt),1,0);
INSERT INTO compact_budget_guard SELECT IF((SELECT COUNT(*) FROM audit_event WHERE kind='MODEL_QUOTA_OBSERVATION')=(SELECT COUNT(*) FROM `__SOURCE_SCHEMA__`.agent_model_budget_observation),1,0);
INSERT INTO compact_budget_guard SELECT IF((SELECT COUNT(*) FROM audit_event WHERE kind='LLM_LEGACY_BUDGET_AUDIT')=(SELECT COUNT(*) FROM `__SOURCE_SCHEMA__`.agent_model_budget_audit),1,0);
INSERT INTO compact_budget_guard SELECT IF((SELECT COUNT(*) FROM llm_usage WHERE entry_type='IMPORTED_USAGE')=(SELECT COUNT(*) FROM `__SOURCE_SCHEMA__`.agent_model_budget_attempt),1,0);
INSERT INTO compact_budget_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_model_budget s LEFT JOIN llm_quota t ON t.scope_type='MODEL' AND t.owner_user_id IS NULL AND t.period_key='TOTAL' AND BINARY t.model_id=BINARY s.model_id WHERE t.id IS NULL OR NOT(BINARY t.scope_type<=>BINARY 'MODEL') OR NOT(BINARY t.period_key<=>BINARY 'TOTAL') OR NOT(t.total_tokens<=>s.total_tokens) OR NOT(t.reserved_tokens<=>0) OR NOT(t.spent_tokens<=>(SELECT COALESCE(SUM(COALESCE(a.input_tokens,0)+COALESCE(a.output_tokens,0)),0) FROM `__SOURCE_SCHEMA__`.agent_model_budget_attempt a WHERE a.model_id=s.model_id)) OR NOT(t.unreconciled_legacy_attempts<=>(SELECT COUNT(*) FROM `__SOURCE_SCHEMA__`.agent_model_budget_attempt a WHERE a.model_id=s.model_id AND (a.status<>'COMPLETED' OR a.finished_at IS NULL OR a.input_tokens IS NULL OR a.output_tokens IS NULL))) OR NOT(t.warning_percent<=>s.warning_percent) OR NOT(t.free_only<=>s.free_only) OR NOT(t.expires_at<=>s.expires_at) OR NOT(t.version<=>s.version) OR NOT(t.updated_by<=>s.updated_by) OR NOT(t.updated_at<=>s.updated_at) OR NOT(t.created_at<=>@compact_budget_imported_at);
INSERT INTO compact_budget_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_model_budget_attempt s LEFT JOIN audit_event t ON BINARY t.legacy_source=BINARY 'agent_model_budget_attempt' AND BINARY t.legacy_key=BINARY CAST(s.id AS CHAR) WHERE t.id IS NULL OR NOT(BINARY t.kind<=>BINARY 'LLM_LEGACY_ATTEMPT') OR NOT(BINARY t.legacy_source<=>BINARY 'agent_model_budget_attempt') OR NOT(BINARY t.resource_type<=>BINARY 'LLM_MODEL') OR NOT(BINARY t.resource_id<=>BINARY s.model_id) OR NOT(t.payload_version<=>1) OR NOT(BINARY t.payload_json<=>BINARY JSON_OBJECT('legacyId',CAST(s.id AS CHAR),'attemptId',s.attempt_id,'modelId',s.model_id,'status',s.status,'inputTokens',s.input_tokens,'outputTokens',s.output_tokens,'cachedTokens',s.cached_tokens,'startedAtUtc',DATE_FORMAT(s.started_at,'%Y-%m-%d %H:%i:%s.%f'),'finishedAtUtc',DATE_FORMAT(s.finished_at,'%Y-%m-%d %H:%i:%s.%f'))) OR NOT(t.session_id IS NULL) OR NOT(t.message_id IS NULL) OR NOT(t.run_id IS NULL) OR NOT(t.sequence_no IS NULL) OR NOT(t.revision IS NULL) OR NOT(t.policy_version IS NULL) OR NOT(t.previous_sha256 IS NULL) OR NOT(t.event_sha256 IS NULL) OR NOT(BINARY t.event_id<=>BINARY CONCAT('legacy-model-attempt-',s.id)) OR NOT(t.owner_user_id IS NULL) OR NOT(t.actor_user_id IS NULL) OR NOT(BINARY t.request_id<=>BINARY s.attempt_id) OR NOT(BINARY t.action<=>BINARY 'IMPORTED') OR NOT(BINARY t.outcome<=>BINARY s.status) OR NOT(BINARY t.content_sha256<=>BINARY SHA2(JSON_OBJECT('legacyId',CAST(s.id AS CHAR),'attemptId',s.attempt_id,'modelId',s.model_id,'status',s.status,'inputTokens',s.input_tokens,'outputTokens',s.output_tokens,'cachedTokens',s.cached_tokens,'startedAtUtc',DATE_FORMAT(s.started_at,'%Y-%m-%d %H:%i:%s.%f'),'finishedAtUtc',DATE_FORMAT(s.finished_at,'%Y-%m-%d %H:%i:%s.%f')),256)) OR NOT(t.occurred_at<=>COALESCE(s.finished_at,s.started_at)) OR NOT(t.request_scope IS NULL) OR NOT(t.quantity IS NULL) OR NOT(t.unit IS NULL) OR NOT(t.observed_at IS NULL);
INSERT INTO compact_budget_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_model_budget_observation s LEFT JOIN audit_event t ON BINARY t.legacy_source=BINARY 'agent_model_budget_observation' AND BINARY t.legacy_key=BINARY CAST(s.id AS CHAR) WHERE t.id IS NULL OR NOT(BINARY t.kind<=>BINARY 'MODEL_QUOTA_OBSERVATION') OR NOT(BINARY t.legacy_source<=>BINARY 'agent_model_budget_observation') OR NOT(BINARY t.resource_type<=>BINARY 'LLM_MODEL') OR NOT(BINARY t.resource_id<=>BINARY s.model_id) OR NOT(t.payload_version<=>1) OR NOT(BINARY t.payload_json<=>BINARY JSON_OBJECT('sourceNote',s.source_note)) OR NOT(t.session_id IS NULL) OR NOT(t.message_id IS NULL) OR NOT(t.run_id IS NULL) OR NOT(t.sequence_no IS NULL) OR NOT(t.revision IS NULL) OR NOT(t.policy_version IS NULL) OR NOT(t.previous_sha256 IS NULL) OR NOT(t.event_sha256 IS NULL) OR NOT(BINARY t.event_id<=>BINARY CONCAT('legacy-model-observation-',s.id)) OR NOT(t.owner_user_id<=>s.actor_user_id) OR NOT(t.actor_user_id<=>s.actor_user_id) OR NOT(BINARY t.request_id<=>BINARY s.request_id) OR NOT(BINARY t.content_sha256<=>BINARY s.request_sha256) OR NOT(BINARY t.action<=>BINARY 'OBSERVATION') OR NOT(t.quantity<=>s.remaining_tokens) OR NOT(BINARY t.unit<=>BINARY 'TOKENS') OR NOT(BINARY t.request_scope<=>BINARY CONCAT('OWNER:',s.actor_user_id)) OR NOT(t.observed_at<=>s.observed_at) OR NOT(t.occurred_at<=>s.created_at) OR NOT(t.outcome IS NULL);
INSERT INTO compact_budget_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_model_budget_audit s LEFT JOIN audit_event t ON BINARY t.legacy_source=BINARY 'agent_model_budget_audit' AND BINARY t.legacy_key=BINARY CAST(s.id AS CHAR) WHERE t.id IS NULL OR NOT(BINARY t.kind<=>BINARY 'LLM_LEGACY_BUDGET_AUDIT') OR NOT(BINARY t.legacy_source<=>BINARY 'agent_model_budget_audit') OR NOT(BINARY t.resource_type<=>BINARY 'LLM_MODEL') OR NOT(BINARY t.resource_id<=>BINARY s.model_id) OR NOT(t.payload_version<=>1) OR NOT(BINARY t.payload_json<=>BINARY JSON_OBJECT('legacyId',CAST(s.id AS CHAR),'modelId',s.model_id,'actorUserId',s.actor_user_id,'actionName',s.action_name,'version',s.version,'detailJson',CAST(s.detail_json AS CHAR),'createdAtUtc',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f'))) OR NOT(t.session_id IS NULL) OR NOT(t.message_id IS NULL) OR NOT(t.run_id IS NULL) OR NOT(t.sequence_no IS NULL) OR NOT(t.revision IS NULL) OR NOT(t.policy_version IS NULL) OR NOT(t.previous_sha256 IS NULL) OR NOT(t.event_sha256 IS NULL) OR NOT(BINARY t.event_id<=>BINARY CONCAT('legacy-model-policy-audit-',s.id)) OR NOT(t.owner_user_id<=>s.actor_user_id) OR NOT(t.actor_user_id<=>s.actor_user_id) OR NOT(BINARY t.action<=>BINARY 'IMPORTED') OR NOT(t.request_id IS NULL) OR NOT(t.request_scope IS NULL) OR NOT(BINARY t.content_sha256<=>BINARY SHA2(JSON_OBJECT('legacyId',CAST(s.id AS CHAR),'modelId',s.model_id,'actorUserId',s.actor_user_id,'actionName',s.action_name,'version',s.version,'detailJson',CAST(s.detail_json AS CHAR),'createdAtUtc',DATE_FORMAT(s.created_at,'%Y-%m-%d %H:%i:%s.%f')),256)) OR NOT(t.occurred_at<=>s.created_at) OR NOT(t.outcome IS NULL) OR NOT(t.quantity IS NULL) OR NOT(t.unit IS NULL) OR NOT(t.observed_at IS NULL);
INSERT INTO compact_budget_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.agent_model_budget_attempt s LEFT JOIN llm_usage t ON t.entry_type='IMPORTED_USAGE' AND t.entry_key='V64_ATTEMPT' AND t.source_audit_event_id=(SELECT e.id FROM audit_event e WHERE BINARY e.legacy_source=BINARY 'agent_model_budget_attempt' AND BINARY e.legacy_key=BINARY CAST(s.id AS CHAR)) WHERE t.id IS NULL OR NOT(BINARY t.entry_type<=>BINARY 'IMPORTED_USAGE') OR NOT(BINARY t.entry_key<=>BINARY 'V64_ATTEMPT') OR NOT(t.account_id<=>(SELECT q.id FROM llm_quota q WHERE q.scope_type='MODEL' AND q.owner_user_id IS NULL AND q.period_key='TOTAL' AND q.model_id=s.model_id)) OR NOT(t.root_operation_id IS NULL) OR NOT(t.operation_id IS NULL) OR NOT(t.actor_user_id IS NULL) OR NOT(t.reserved_delta<=>0) OR NOT(t.spent_delta<=>COALESCE(s.input_tokens,0)+COALESCE(s.output_tokens,0)) OR NOT(t.input_tokens<=>s.input_tokens) OR NOT(t.output_tokens<=>s.output_tokens) OR NOT(t.cached_tokens<=>s.cached_tokens) OR NOT(t.limit_before IS NULL) OR NOT(t.limit_after IS NULL) OR NOT(BINARY t.request_sha256<=>BINARY SHA2(CONCAT('V64_IMPORT',CHAR(10),JSON_OBJECT('legacyId',CAST(s.id AS CHAR),'attemptId',s.attempt_id,'modelId',s.model_id,'status',s.status,'inputTokens',s.input_tokens,'outputTokens',s.output_tokens,'cachedTokens',s.cached_tokens,'startedAtUtc',DATE_FORMAT(s.started_at,'%Y-%m-%d %H:%i:%s.%f'),'finishedAtUtc',DATE_FORMAT(s.finished_at,'%Y-%m-%d %H:%i:%s.%f'))),256)) OR NOT(t.created_at<=>COALESCE(s.finished_at,s.started_at));
